command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="9dd0316236849b18956117a592b21124f2d67c0b"
$candidate="e70f34b9c291eb2b4678af3ba2145bf25b36d76e"
$branch="work/window-tab-large-icons-20261006"
$base=Join-Path $env:RUNNER_TEMP ("fly-window-tab-base-"+$env:GITHUB_RUN_ID)
$cand=Join-Path $env:RUNNER_TEMP ("fly-window-tab-cand-"+$env:GITHUB_RUN_ID)
$evidence=Join-Path $repo "logs\remote-evidence"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "window-tab fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before window-tab acceptance"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "window-tab candidate moved"}
foreach($p in @($base,$cand)){
  if(Test-Path -LiteralPath $p){& git worktree remove --force $p 2>$null;Remove-Item -LiteralPath $p -Recurse -Force -ErrorAction SilentlyContinue}
}
& git worktree add --detach $base $main
if($LASTEXITCODE -ne 0){throw "baseline worktree creation failed"}
& git worktree add --detach $cand $candidate
if($LASTEXITCODE -ne 0){throw "candidate worktree creation failed"}
try{
  Set-Location -LiteralPath $cand
  & git diff --check ($main+"..."+$candidate)
  if($LASTEXITCODE -ne 0){throw "window-tab diff check failed"}
  & python -X utf8 tools\winui\run_checks.py fast --before $main --head $candidate
  if($LASTEXITCODE -ne 0){throw "window-tab FAST failed"}

  Set-Location -LiteralPath $base
  & .\build.bat Release
  if($LASTEXITCODE -ne 0){throw "baseline Release build failed"}

  Set-Location -LiteralPath $cand
  & .\build.bat Release
  if($LASTEXITCODE -ne 0){throw "candidate Release build failed"}

  $script=Join-Path $cand "tests\winui\test_window_tab_large_icons_gui.py"
  $baseExe=Join-Path $base "out\winui\Release\flyExplorer.exe"
  $candExe=Join-Path $cand "out\winui\Release\flyExplorer.exe"

  & python -X utf8 $script --configuration Release --exe $baseExe --expect medium --capture before
  if($LASTEXITCODE -ne 0){throw "baseline Medium clamp reproduction failed"}

  & python -X utf8 $script --configuration Release --exe $candExe --expect large --capture after
  if($LASTEXITCODE -ne 0){throw "candidate Large Icons preservation failed"}

  New-Item -ItemType Directory -Path $evidence -Force | Out-Null
  foreach($name in @("window-tab-large-icons-before.png","window-tab-large-icons-after.png")){
    $shot=Join-Path $cand ("logs\window-tab-large-icons\"+$name)
    if(!(Test-Path -LiteralPath $shot -PathType Leaf)){throw "missing visual evidence: $name"}
    Copy-Item -LiteralPath $shot -Destination (Join-Path $evidence $name) -Force
  }
  Write-Host "WINDOW_TAB_LARGE_ICONS_FAST=PASS"
  Write-Host "WINDOW_TAB_LARGE_ICONS_BASELINE=PASS"
  Write-Host "WINDOW_TAB_LARGE_ICONS_CANDIDATE=PASS"
  Write-Host "WINDOW_TAB_LARGE_ICONS_VISUAL=EXPORTED"
} finally {
  Set-Location -LiteralPath $repo
  foreach($p in @($base,$cand)){if(Test-Path -LiteralPath $p){& git worktree remove --force $p}}
  & git worktree prune
}
